function applySpec(
  spec: $.introspect.Types,
  type: $.introspect.ObjectType,
  shape: any,
  seen: Set<string>,
  literal: any,
): void {
  const allPointers = [
    ...type.pointers,
    ...type.backlinks,
    ...type.backlink_stubs,
  ];
